[
  {
    "sys_fairness_reciprocity": "I'd count on a stranger to do the same for me, so I owe them",
    "ce_mentalizing_difficulty": "I just can't get inside their heads from a platform.",
    "pda_other_regret_expectation": "Would any of them regret being out there? I honestly can't say.",
    "pd_decision_conflict": "My stomach drops just picturing it"
  },
  {
    "sys_consequence_reasoning": "it keeps the train away from five people, and when the price is zero",
    "ce_mentalizing_difficulty": "I can't work out what was going on in their mind",
    "pda_other_regret_expectation": "Whether they'll regret it later, I truly don't know.",
    "pd_harm_distress": "What unsettles me is the person who left that train"
  },
  {
    "sys_fairness_reciprocity": "Everyone on that track deserves the same protection I'd want",
    "ce_mentalizing_difficulty": "I keep trying to guess how the foreman would take a random bystander",
    "pda_other_regret_expectation": "Would he regret sending the crew out without a lookout? I can't call it",
    "pd_decision_conflict": "my hands would probably be shaking."
  },
  {
    "sys_fairness_reciprocity": "if the positions were swapped, I'd expect someone to act for me",
    "ce_mentalizing_difficulty": "I can't figure them out, and that's my own limit",
    "pda_other_regret_expectation": "Whether any would regret being on that stretch, I couldn't predict.",
    "pd_decision_conflict": "I'd be sick with nerves the whole time."
  },
  {
    "sys_consequence_reasoning": "doing it is just matching the tiny effort to the huge stakes.",
    "ce_mentalizing_difficulty": "I can't make sense of whoever should have secured that train.",
    "pda_other_regret_expectation": "Would they regret it? No idea.",
    "pd_decision_conflict": "I'd feel uneasy afterward"
  },
  {
    "sys_fairness_reciprocity": "Every one of those workers counts as much as I would",
    "ce_mentalizing_difficulty": "I can't tell what the maintenance crew's supervisor expects",
    "pda_other_regret_expectation": "Does that supervisor regret how the day was set up? I can't guess.",
    "pd_decision_conflict": "something nags at me."
  },
  {
    "sys_fairness_reciprocity": "Everyone gets the same claim on help, and the cost here is zero",
    "ce_mentalizing_difficulty": "Reading that person is beyond me",
    "pda_other_regret_expectation": "I can't tell you whether they'd regret leaving it.",
    "pd_decision_conflict": "Part of me freezes"
  },
  {
    "sys_fairness_reciprocity": "we all carry a sort of debt to one another in moments like this",
    "ce_mentalizing_difficulty": "not knowing how any of those five would receive a stranger's intervention.",
    "pda_other_regret_expectation": "Would any of them regret having gone out? Hard to predict.",
    "pd_decision_conflict": "I'd feel awful standing there doing nothing"
  },
  {
    "sys_fairness_reciprocity": "Refusing would mean giving them less than I'd demand for myself.",
    "ce_mentalizing_difficulty": "I genuinely can't picture their state of mind",
    "pda_other_regret_expectation": "Whether they'll look back and regret the lapse, I can't tell.",
    "pd_decision_conflict": "Tight feeling in my chest"
  },
  {
    "sys_fairness_reciprocity": "every person on that track has an equal right to it.",
    "ce_mentalizing_difficulty": "I can't work out what they'd have expected a passenger to do",
    "pda_other_regret_expectation": "Would they regret stepping away? I really don't know.",
    "pd_decision_conflict": "I'd be jittery for hours."
  }
]
